const $ = s => document.querySelector(s);
const typeNames = {feature:'專題報導',news:'新聞採訪',interactive:'數位敘事'};
const escapeHtml = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function artwork(type){
 const palettes={dementia:['#cbd5c6','#6d8273','#f1f2e9'],cafe:['#d9cfc3','#877362','#f3e9dc'],body:['#cbd8e2','#6e8da6','#eff4f7'],digital:['#bdccd9','#4b6584','#e9f0f4'],campus:['#d7d8c9','#777d66','#f2f0e8'],culture:['#ddcfbf','#8d7663','#f4eddf'],train:['#cadce5','#607e93','#eff5f6'],science:['#ded6c9','#8b8070','#f5f1e8'],nature:['#c9d5c9','#728b77','#edf2e9']};
 const [bg,ink,paper]=palettes[type]||palettes.culture;
 let shapes='';
 if(type==='dementia') shapes=`<rect x="105" y="55" width="220" height="140" fill="${paper}"/><path d="M105 90H325M177 55V195M250 55V195" stroke="${bg}" stroke-width="3"/><path d="M165 240V172H263V240M166 211H263" stroke="${ink}" stroke-width="6" fill="none"/><path d="M178 171V126Q215 113 252 126V171" fill="${ink}" opacity=".7"/><circle cx="295" cy="218" r="25" fill="${paper}"/><path d="M295 200V218L306 226" stroke="${ink}" stroke-width="2"/><path d="M75 245H355" stroke="${ink}"/>`;
 else if(type==='cafe') shapes=`<path d="M0 60H430M50 0V300M380 0V300" stroke="${ink}" opacity=".2"/><path d="M50 60Q120 170 190 60M240 60Q310 170 380 60" stroke="${ink}" opacity=".4" fill="none"/><ellipse cx="215" cy="230" rx="133" ry="28" fill="${ink}" opacity=".25"/><path d="M120 157H196L188 214H129Z" fill="${paper}"/><path d="M196 168Q223 166 220 181Q220 198 193 198" stroke="${paper}" stroke-width="8" fill="none"/><ellipse cx="276" cy="202" rx="41" ry="12" fill="${paper}"/><path d="M241 200Q247 165 277 164Q306 165 312 200" fill="${ink}" opacity=".7"/><circle cx="276" cy="153" r="7" fill="${paper}"/><path d="M161 139Q148 125 161 111" stroke="${ink}" stroke-width="2" fill="none"/>`;
 else if(type==='body') shapes=`<rect x="76" y="36" width="155" height="231" rx="77" fill="${paper}" stroke="${ink}" stroke-width="2"/><path d="M118 224Q102 188 136 159Q126 137 135 114Q148 93 167 113Q180 133 165 159Q201 185 187 224Z" fill="${bg}" stroke="${ink}" stroke-width="2"/><rect x="264" y="69" width="99" height="160" rx="12" fill="${ink}" transform="rotate(8 314 150)"/><rect x="274" y="80" width="79" height="127" rx="5" fill="${paper}" transform="rotate(8 314 150)"/><path d="M289 118H337M289 129H326M289 175H336" stroke="${ink}" opacity=".6"/><circle cx="313" cy="150" r="12" fill="${bg}"/><text x="65" y="285" fill="${ink}" font-size="8" letter-spacing="3">BEYOND THE REFLECTION</text>`;
 else if(type==='digital') shapes=`<rect x="94" y="59" width="247" height="165" rx="3" fill="${ink}"/><rect x="105" y="71" width="225" height="139" fill="${bg}"/><path d="M168 204V171Q180 149 212 150Q242 151 254 174V204" fill="${paper}" opacity=".7"/><circle cx="212" cy="118" r="25" fill="${paper}" opacity=".8"/><path d="M200 224V251M175 251H258" stroke="${ink}" stroke-width="7"/><path d="M105 112H330M105 153H330M164 71V210M269 71V210" stroke="${ink}" opacity=".12"/><g fill="${ink}" opacity=".4"><rect x="241" y="96" width="14" height="14"/><rect x="262" y="115" width="9" height="9"/><rect x="283" y="138" width="16" height="16"/></g>`;
 else if(type==='campus') shapes=`<path d="M63 263V127H360V263" fill="${paper}"/><path d="M46 128L213 51L379 128Z" fill="${ink}" opacity=".7"/><g fill="${bg}"><rect x="86" y="151" width="31" height="95"/><rect x="139" y="151" width="31" height="95"/><rect x="192" y="151" width="31" height="95"/><rect x="245" y="151" width="31" height="95"/><rect x="298" y="151" width="31" height="95"/></g><path d="M38 263H390" stroke="${ink}" stroke-width="3"/><rect x="270" y="202" width="91" height="59" fill="${ink}" transform="rotate(-7 320 230)"/><path d="M282 222H345M281 233H331" stroke="${paper}" stroke-width="2"/>`;
 else if(type==='train') shapes=`<path d="M0 249H430M0 264H430" stroke="${ink}" stroke-width="2"/><rect x="65" y="122" width="291" height="119" rx="17" fill="${paper}" stroke="${ink}" stroke-width="2"/><path d="M67 208H354" stroke="${ink}" stroke-width="6"/><g fill="${bg}"><rect x="81" y="143" width="49" height="42" rx="3"/><rect x="144" y="143" width="49" height="42" rx="3"/><rect x="208" y="143" width="49" height="42" rx="3"/><rect x="276" y="143" width="57" height="85" rx="4"/></g><circle cx="111" cy="245" r="9" fill="${ink}"/><circle cx="311" cy="245" r="9" fill="${ink}"/><path d="M0 82H430M122 0V83M327 0V83" stroke="${ink}" opacity=".3"/><text x="75" y="105" fill="${ink}" font-size="10" letter-spacing="4">SCIENCE ON THE MOVE</text>`;
 else if(type==='nature') shapes=`<path d="M0 270L79 137L130 202L226 85L330 220L389 152L430 226V300H0" fill="${ink}" opacity=".4"/><path d="M0 284L153 212L224 248L339 181L430 246V300H0" fill="${paper}"/><path d="M146 91Q163 73 181 91Q199 72 217 91" stroke="${ink}" stroke-width="3" fill="none"/><path d="M255 71Q267 57 279 71Q291 57 303 71" stroke="${ink}" stroke-width="2" fill="none"/><circle cx="83" cy="72" r="24" fill="${paper}"/>`;
 else if(type==='science') shapes=`<g fill="none" stroke="${ink}" stroke-width="2"><ellipse cx="213" cy="151" rx="126" ry="45" transform="rotate(25 213 151)"/><ellipse cx="213" cy="151" rx="126" ry="45" transform="rotate(-25 213 151)"/><ellipse cx="213" cy="151" rx="45" ry="119"/></g><circle cx="213" cy="151" r="25" fill="${paper}"/><circle cx="107" cy="122" r="9" fill="${ink}"/><circle cx="291" cy="220" r="9" fill="${ink}"/><circle cx="224" cy="35" r="8" fill="${ink}"/>`;
 else shapes=`<path d="M78 94L208 119V249L78 220Z" fill="${paper}" stroke="${ink}" stroke-width="2"/><path d="M208 119L348 94V220L208 249Z" fill="${paper}" stroke="${ink}" stroke-width="2"/><path d="M98 126L184 142M98 146L184 162M98 166L184 182M232 140L326 124M232 160L326 144M232 180L300 169" stroke="${ink}" opacity=".45"/><path d="M183 58Q198 35 213 58Q228 35 244 58" stroke="${ink}" stroke-width="2" fill="none"/><circle cx="352" cy="54" r="17" fill="${paper}"/>`;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 430 300" aria-hidden="true"><rect width="430" height="300" fill="${bg}"/>${shapes}<text x="17" y="282" font-family="monospace" font-size="8" letter-spacing="1.5" fill="${ink}">KATY’S TOUR / EDITORIAL ILLUSTRATION</text></svg>`;
}
let filter='all', expanded=false;
function renderStories(){
 const matched=stories.map((s,i)=>({...s,index:i})).filter(s=>filter==='all'||s.type===filter);
 const visible=expanded?matched:matched.slice(0,6);
 $('#story-grid').innerHTML=visible.map(s=>`<button class="story-card" data-story="${s.index}" aria-label="查看作品：${escapeHtml(s.title)}"><div class="story-cover">${artwork(s.art)}<span class="cover-label">${typeNames[s.type]} / ${s.type.toUpperCase()}</span></div><div class="story-meta"><span>${s.topic}</span><span>${s.date||'政大大學報'}</span></div><h3>${s.type==='interactive'?'【融媒體】':''}${s.title}</h3><p>${s.summary||'從事件與人物出發，記錄公共議題與生活現場。'}</p><div class="story-footer"><span>${s.type==='interactive'?'UI／UX・互動敘事':s.type==='feature'?'專題規劃・共同採訪':'選題・採訪・查證・寫作'}</span><span aria-hidden="true">↗</span></div></button>`).join('');
 $('#story-count').textContent=`${String(visible.length).padStart(2,'0')} / ${String(matched.length).padStart(2,'0')} STORIES`;
 $('#show-more').hidden=matched.length<=6;
 $('#show-more').innerHTML=expanded?'收合作品清單 <span>↑</span>':`查看全部 ${matched.length} 件作品 <span>↓</span>`;
}
$('.filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;expanded=false;document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b))});renderStories()});
$('#show-more').addEventListener('click',()=>{expanded=!expanded;renderStories();if(!expanded)$('#stories').scrollIntoView({behavior:'smooth'})});
const dialog=$('#story-dialog');
function openStory(index){
 const s=stories[index];
 $('#dialog-content').innerHTML=`<p class="eyebrow">${typeNames[s.type]} / ${s.topic}</p><h2>${s.type==='interactive'?'【融媒體】':''}${s.title}</h2><div class="dialog-art">${artwork(s.art)}</div><p>${s.summary||'這篇報導以事件為起點，關注新聞現場的人物、公共議題與生活經驗。完整內容請閱讀已刊登報導。'}</p><dl><dt>刊登平台${s.date?'／日期':''}</dt><dd>政大大學報${s.date?' · '+s.date:''}</dd><dt>我的角色與工作</dt><dd>${s.role||'國際與生活版純淨新聞期間，負責選題、採訪、查證與稿件撰寫。'}</dd><dt>採訪／製作方法</dt><dd>${s.method||'新聞資料蒐集、採訪與查證；個別作品的方法細節待補充。'}</dd>${s.region?`<dt>報導議題所在地</dt><dd>${s.region}（依作品內容分類，不代表實際赴當地採訪）</dd>`:''}<dt>封面來源</dt><dd>原創主題示意插畫，非報導現場照片。</dd></dl><a class="button primary" target="_blank" rel="noopener" href="https://unews.nccu.edu.tw/unews/${s.slug}/">閱讀已刊登作品 <span>↗</span></a>`;
 dialog.showModal();
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-story]');if(b)openStory(Number(b.dataset.story))});
$('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
$('#timeline').innerHTML=experiences.map(x=>`<article class="timeline-item"><time>${x.date}</time>${x.current?'<span class="current">目前停靠</span>':''}<h4>${x.org}</h4><div class="position">${x.position}</div><p>${x.text}</p></article>`).join('');
$('#skills').innerHTML=skillGroups.map(x=>`<div class="skill-group"><h5>${x.title}</h5><p>${x.text}</p></div>`).join('');
const routes={taiwan:[{name:'台北',en:'TAIPEI'},{name:'新竹',en:'HSINCHU'},{name:'台東',en:'TAITUNG'},{name:'花蓮',en:'HUALIEN'},{name:'屏東',en:'PINGTUNG'}],world:[{name:'美國',en:'UNITED STATES'},{name:'英國',en:'UNITED KINGDOM'},{name:'香港',en:'HONG KONG'}]};
let region='taiwan';
function renderMap(){
 $('#route-visual').innerHTML=`<p class="route-label">${region==='taiwan'?'TAIWAN / 生活與文化線':'WORLD / 校園與公共議題線'}</p><div class="stations">${routes[region].map((x,i)=>`<button class="station ${i===0?'active':''}" data-station="${x.name}" aria-pressed="${i===0}"><span class="node"></span><span>${x.name}</span><small>${x.en}</small></button>`).join('')}</div><div class="route-end">每一站，都是理解世界的另一個入口。　↗</div>`;
 selectStation(routes[region][0].name);
}
function selectStation(name){
 document.querySelectorAll('[data-station]').forEach(b=>{const active=b.dataset.station===name;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});
 const matches=stories.map((s,i)=>({...s,index:i})).filter(s=>s.region===name);
 $('#station-panel').innerHTML=`<p class="eyebrow">STATION / ${String(routes[region].findIndex(x=>x.name===name)+1).padStart(2,'0')}</p><h3>${name}<small style="font-family:var(--sans);font-size:10px;color:var(--muted);margin-left:15px">${matches.length} 件作品</small></h3>${matches.map(s=>`<button class="station-story" data-story="${s.index}">${s.title}<span>閱讀作品詳情 ↗</span></button>`).join('')}`;
}
$('.map-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-region]');if(!b)return;region=b.dataset.region;document.querySelectorAll('[data-region]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b))});renderMap()});
$('#route-visual').addEventListener('click',e=>{const b=e.target.closest('[data-station]');if(b)selectStation(b.dataset.station)});
const books={listen:{title:'在陌生人的故事裡，練習理解。',text:'受訪者願意向初次見面的我敞開心房，是採訪中最珍貴的事。提問、傾聽，再把故事與資料拼起來，是我選擇新聞的理由。'},create:{title:'文字之外，還有新的敘事方法。',text:'從互動裝置、3D 建模到網頁程式，數位內容讓我探索更多表達的可能。在新聞與設計之間，找到讓讀者走進故事的方法。'},life:{title:'留一點時間，給生活本身。',text:'我喜歡和家人朋友好好相聚。獨處時拉小提琴，最近開始學高爾夫；夏天游泳，冬天騎腳踏車通勤，在日常裡讓思緒自由延伸。'}};
$('.shelf').addEventListener('click',e=>{const b=e.target.closest('[data-book]');if(!b)return;const x=books[b.dataset.book];document.querySelectorAll('[data-book]').forEach(el=>el.classList.toggle('active',el===b));$('#book-note').innerHTML=`<span class="eyebrow">A PAGE FROM MY LIFE</span><h3>${x.title}</h3><p>${x.text}</p>`});
$('.menu-button').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('.menu-button').setAttribute('aria-expanded',String(open))});
$('#navigation').addEventListener('click',e=>{if(e.target.closest('a')){$('#navigation').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false')}});
$('#print-resume').addEventListener('click',()=>{const w=window.open('assets/Katy-Huang-Resume-2026-10.pdf','_blank');if(w){w.addEventListener('load',()=>{try{w.print()}catch{}} ,{once:true})}});
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('#navigation a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))})},{rootMargin:'-15% 0px -60% 0px'});
document.querySelectorAll('main>section').forEach(s=>observer.observe(s));
renderStories();renderMap();
